Method.Source:
/// <summary>
/// Called when a recurrence invoice group is selected on the form.
/// Keeps the "Post in Batch" button enabled state in sync with the
/// group's posted status.
/// </summary>
/// <returns>
/// Returns an integer value to the base.
/// </returns>
public int active()
{
    int ret = next active();

    CustRecurrenceInvoiceGroup custRecurrenceInvoiceGroup = this.cursor();
    FormControl                formControl                = this.formRun().design().controlName('METCustRecurrInvoicePostServiceOperation') as FormControl;

    formControl.enabled(custRecurrenceInvoiceGroup.Posted == NoYes::No);

    return ret;
}
